"""Build documentation tokens and an offline visual sample from recorded brand CSS."""
from html import escape
import json
from pathlib import Path
import re

ROOT = Path(__file__).resolve().parents[1]
OUT = ROOT / 'design'
SOURCE = ROOT / 'research' / 'copypaste-brand'

def source_theme(css, pattern):
    block = re.search(pattern,css,re.S).group(1)
    values = dict(re.findall(r'--color-([a-z-]+):\s*([^;]+);',block))
    return {k:v.lower() for k,v in values.items() if k!='shadow'}, values['shadow']

def tokens():
    css = (SOURCE/'styles-source.css').read_text(encoding='utf-8')
    themes = {}
    for name,pattern,control,statuses,chart in [
        ('light',r':root\s*\{(.*?)\}', '#858B95',
         {'success':['#176746','#EAF4EE'],'warning':['#875000','#FFF1D6'],'error':['#B42335','#FDECEF'],'info':['#1F5EFF','#EEF2FF']},
         ['#1F5EFF','#202D45','#0F746B','#7759A5','#8C6400','#5D636D']),
        ('dark',r'html\[data-theme="dark"\]\s*\{(.*?)\}', '#68758D',
         {'success':['#7DD3AB','#142C24'],'warning':['#F5C66F','#302615'],'error':['#FFA4AE','#351E27'],'info':['#79A2FF','#1B2943']},
         ['#79A2FF','#B5C1D8','#7DD3AB','#C5A0E4','#F5C66F','#A0ACC2']),
    ]:
        base,shadow = source_theme(css,pattern)
        semantic = {'action-fill':base['text'],'action-text':base['bg'],'control-border':control.lower(),'focus':base['accent']}
        for status,(ink,soft) in statuses.items():
            semantic[status] = ink.lower()
            semantic[status+'-soft'] = soft.lower()
        themes[name] = {'base_colors':base,'source_shadow':shadow,'product_semantic_colors':semantic,'chart_palette':[c.lower() for c in chart]}
    contrast = [{'foreground':fg,'background':bg,'minimum_ratio':minimum} for fg,bg,minimum in [
        ('text','bg',4.5),('text-muted','bg',4.5),('text','surface',4.5),('text-muted','surface',4.5),
        ('action-text','action-fill',4.5),('accent','surface',4.5),('focus','bg',3),
        ('control-border','surface',3),('control-border','bg',3),
        ('success','success-soft',4.5),('warning','warning-soft',4.5),('error','error-soft',4.5),('info','info-soft',4.5),
    ]]
    return {'version':'1.3.0','status':'design_only','origin_id':'BRAND01',
            'source_url':'https://copypaste.hk/','source_css_url':'https://copypaste.hk/styles.css',
            'source_evidence':'research/copypaste-brand/source-evidence.json',
            'base_color_origin':'official_site_css_snapshot','semantic_color_origin':'product_extension',
            'themes':themes,'default_theme':'light','theme_preferences':['light','dark','system'],
            'fonts':{
                'display':'"Fraunces", "Iowan Old Style", "Noto Serif TC", "Source Han Serif TC", "Noto Serif SC", "Songti TC", "PMingLiU", serif',
                'body':'"Manrope", "Avenir Next", "Segoe UI", "Noto Sans TC", "Noto Sans SC", "PingFang TC", "Microsoft JhengHei", sans-serif',
                'code':'"Cascadia Code", "SFMono-Regular", Consolas, monospace'},
            'font_status':'declared_stacks_with_system_fallback_not_bundled_fonts',
            'spacing_px':[4,8,12,16,20,24,32,40,48],
            'radii_px':{'small':8,'control':12,'compact':14,'card':16,'feature':26,'pill':999},
            'motion_ms':{'fast':160,'standard':180,'panel':220},
            'layout':{'header_px':64,'sidebar_px':240,'dual_panel_min_width_px':1280,'test_widths_px':[375,768,1024,1440]},
            'contrast_pairs':contrast,
            'customer_artifact_theme_policy':'customer_brand_only_platform_theme_does_not_modify_exports',
            'logo_assets':{'light':'../research/copypaste-brand/CopyPaste_Light.png','dark':'../research/copypaste-brand/CopyPaste_Dark.png'}}

def css_text(data):
    blocks = ['/* Generated from brand-tokens.json; recorded official base colors + labelled product extensions. */']
    for theme,values in data['themes'].items():
        selector = ':root, :root[data-theme="light"]' if theme=='light' else ':root[data-theme="dark"]'
        lines = [selector+' {',f'  color-scheme: {theme};']
        for key,value in {**values['base_colors'],**values['product_semantic_colors']}.items():
            lines.append(f'  --cp-color-{key}: {value};')
        for i,color in enumerate(values['chart_palette'],1):
            lines.append(f'  --cp-chart-{i}: {color};')
        lines.append(f'  --cp-shadow: {values["source_shadow"]};')
        if theme=='light':
            for key,value in data['fonts'].items():
                lines.append(f'  --cp-font-{key}: {value};')
            for value in data['spacing_px']:
                lines.append(f'  --cp-space-{value}: {value}px;')
            for key,value in data['radii_px'].items():
                lines.append(f'  --cp-radius-{key}: {value}px;')
            for key,value in data['motion_ms'].items():
                lines.append(f'  --cp-motion-{key}: {value}ms;')
        lines.append('}')
        blocks.append('\n'.join(lines))
    return '\n\n'.join(blocks)+'\n'

